// ==========================================
// 1. VARIABLES GLOBALES & FONCTIONS
// ==========================================

// Variable globale pour le graphique Chart.js
let roiChartInstance = null;

function calculerImpactCA() {
  const trafic = parseFloat(document.getElementById('trafic').value) || 0;
  const ventes = parseFloat(document.getElementById('ventes').value) || 0;
  const panier = parseFloat(document.getElementById('panier').value) || 0;

  // Nettoyage message d'erreur ventes éventuel
  const ventesField = document.getElementById('ventes');
  let erreurVentes = document.getElementById('erreur-ventes');
  if (erreurVentes) erreurVentes.remove();

  if (trafic <= 0 || ventes <= 0 || panier <= 0) {
    alert('Veuillez renseigner tous les champs avec des valeurs positives.');
    return;
  }

  if (ventes > trafic) {
    erreurVentes = document.createElement('p');
    erreurVentes.id = 'erreur-ventes';
    erreurVentes.style.cssText = 'color:#e53e3e;font-size:0.85rem;margin-top:4px;';
    erreurVentes.textContent = 'Le nombre de ventes ne peut pas dépasser le trafic.';
    ventesField.parentNode.appendChild(erreurVentes);
    return;
  }

  // === LOGIQUE DE CALCUL V3.1 ===
  const TAUX_HAUSSE_TRAFIC_DEFAULT = 0.10;
  const K_CONVERSION_RELATIVE = 0.435;

  // Situation AVANT
  const caAvant = ventes * panier;

  // Trafic après
  const uT = TAUX_HAUSSE_TRAFIC_DEFAULT;
  const traficApres = trafic * (1 + uT);

  // Transactions incrémentales
  const deltaV_brut = ventes * uT * K_CONVERSION_RELATIVE;
  const ventesApres_brut = ventes + deltaV_brut;
  const ventesApres = Math.min(ventesApres_brut, traficApres);
  const deltaV = ventesApres - ventes;

  // CA après — panier constant
  const panierApres = panier;
  const deltaCA = deltaV * panier;
  const caApres = caAvant + deltaCA;

  // Gains
  const gainMensuel = deltaCA;
  const gainAnnuel = deltaCA * 12;

  // Pourcentages badges
  const pctTrafic = uT * 100;
  const pctVentes = (deltaV / ventes) * 100;
  const pctCA = (deltaCA / caAvant) * 100;

  // === AFFICHAGE ===
  document.getElementById('trafic_avant').textContent = formatNumber(trafic) + ' visiteurs';
  document.getElementById('ventes_avant').textContent = formatNumber(ventes) + ' ventes';
  document.getElementById('panier_avant').textContent = formatEuro(panier);
  document.getElementById('ca_avant').textContent = formatEuro(caAvant);

  document.getElementById('trafic_apres').textContent = formatNumber(Math.round(traficApres)) + ' visiteurs';
  document.getElementById('ventes_apres').textContent = formatNumber(Math.round(ventesApres)) + ' ventes';
  document.getElementById('panier_apres').textContent = formatEuro(panierApres);
  document.getElementById('ca_apres').textContent = formatEuro(caApres);

  document.getElementById('gain_mensuel').textContent = formatEuro(gainMensuel);
  document.getElementById('gain_annuel').textContent = formatEuro(gainAnnuel);

  // === MISE À JOUR DES BADGES ===
  const badgeTrafic = document.querySelector('#trafic_apres').previousElementSibling;
  const badgeVentes = document.querySelector('#ventes_apres').previousElementSibling;
  const badgePanier = document.querySelector('#panier_apres').previousElementSibling;
  const badgeCA     = document.querySelector('#ca_apres').previousElementSibling;

  if (badgeTrafic && badgeTrafic.classList.contains('metric-badge'))
    badgeTrafic.textContent = '+' + pctTrafic.toFixed(0) + '%';
  if (badgeVentes && badgeVentes.classList.contains('metric-badge'))
    badgeVentes.textContent = '+' + pctVentes.toFixed(1).replace('.', ',') + '%';
  if (badgePanier && badgePanier.classList.contains('metric-badge'))
    badgePanier.style.display = 'none';
  if (badgeCA && badgeCA.classList.contains('metric-badge'))
    badgeCA.textContent = '+' + pctCA.toFixed(1).replace('.', ',') + '%';

  // === MISE À JOUR DU GRAPHIQUE ===
  updateChart(caAvant, caApres);

  // Affichage de la section résultats
  const resultsSection = document.getElementById('results');
  resultsSection.style.display = 'block';
  
  // Réveil de la section externe HubSpot (si elle existe)
  const sectionRassurance = document.getElementById('section-rassurance');
  if (sectionRassurance) {
    sectionRassurance.style.display = 'block';
  }

  setTimeout(function() {
    resultsSection.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }, 100);

  // === TRACKING & TRANSFERT ===
  const donneesATransferer = {
    'trafic_visiteurs_mensuel': trafic,
    'gain_mensuel_estime': Math.round(gainMensuel)
  };

  for (const [nomInterne, valeur] of Object.entries(donneesATransferer)) {
    const champ = document.querySelector(`input[name="${nomInterne}"]`);
    if (champ) {
      champ.value = valeur;
      champ.dispatchEvent(new Event('input', { bubbles: true }));
      champ.dispatchEvent(new Event('change', { bubbles: true }));
    }
  }

  if (typeof window._hsq !== 'undefined') {
    window._hsq.push(['trackCustomBehavioralEvent', {
      name: 'calculateur_ca_utilise',
      properties: { gain_mensuel: gainMensuel }
    }]);
  }
}

// === LOGIQUE GRAPHIQUE ===
function updateChart(caAvantMensuel, caApresMensuel) {
  const canvas = document.getElementById('roiChart');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  
  // Projection annuelle
  const caAvantAn = caAvantMensuel * 12;
  const caApresAn = caApresMensuel * 12;
  
  const dataSans = [0, caAvantAn, caAvantAn * 2, caAvantAn * 3];
  const dataAvec = [0, caApresAn, caApresAn * 2, caApresAn * 3];

  if (roiChartInstance) roiChartInstance.destroy();

  roiChartInstance = new Chart(ctx, {
    type: 'line',
    data: {
      labels: ['Départ', 'Année 1', 'Année 2', 'Année 3'],
      datasets: [
        {
          label: 'Situation Actuelle',
          data: dataSans,
          borderColor: '#999', borderWidth: 2, borderDash: [5,5], pointRadius: 3
        },
        {
          label: 'Avec Écran AKAIRO',
          data: dataAvec,
          borderColor: '#DE0B19', backgroundColor: 'rgba(222, 11, 25, 0.1)',
          borderWidth: 3, pointRadius: 5, pointBackgroundColor: '#FFF', pointBorderColor: '#DE0B19',
          fill: '-1', tension: 0.3
        }
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      animation: {
          duration: 1000 
      },
      plugins: { legend: { position: 'bottom' }, tooltip: { mode: 'index', intersect: false } },
      scales: { y: { beginAtZero: true, ticks: { callback: v => v >= 1000 ? (v/1000) + ' k€' : v + ' €' } } }
    }
  });
}

// === TÉLÉCHARGEMENT PDF AVEC BRANDING (METHODE CALQUE & NETTOYAGE) ===
function downloadPDF() {
  const element = document.getElementById('results');
  const btn = document.querySelector('.btn-download-pdf');
  
  // 1. Préparation visuelle
  element.classList.add('pdf-mode');
  
  // Gestion propre des sauts de page
  const gainMensuel = document.querySelector('.gain-mensuel');
  if (gainMensuel) {
    gainMensuel.style.pageBreakAfter = 'always';
    gainMensuel.style.breakAfter = 'page';
  }

  if (btn) {
      btn.textContent = 'Génération en cours...';
      btn.disabled = true;
      btn.style.opacity = '0.7';
  }

  // --- CONFIGURATION DU BRANDING ---
  
  // A. VOTRE IMAGE DE MARQUE (Format A4 - PNG Transparent)
  const brandingBase64 = "data:image/png;base64,"; 

  // B. MARGES DE SÉCURITÉ (en mm)
  // [Haut, Droite, Bas, Gauche]
  // CORRECTION MAJEURE : Marge du bas à 0 pour éviter le débordement fantôme
  const opt = {
    margin:       [40, 10, 0, 10], 
    filename:     'Simulation-ROI-AKAIRO.pdf',
    image:        { type: 'jpeg', quality: 0.98 },
    html2canvas:  { scale: 2, useCORS: true, scrollY: 0 },
    jsPDF:        { unit: 'mm', format: 'a4', orientation: 'portrait' }
  };

  // 3. GÉNÉRATION ET APPLICATION DU CALQUE
  setTimeout(() => {
      html2pdf().from(element).set(opt).toPdf().get('pdf').then(function(pdf) {
          // --- ETAPE DE NETTOYAGE (FAIL-SAFE) ---
          // Si le PDF a plus de 2 pages à cause d'un débordement invisible, on supprime les pages en trop.
          const initialPages = pdf.internal.getNumberOfPages();
          if (initialPages > 2) {
              // On supprime en partant de la fin pour ne pas casser l'index
              for (let i = initialPages; i > 2; i--) {
                  pdf.deletePage(i);
              }
          }

          // --- APPLICATION DU BRANDING ---
          // On ne boucle que sur les pages restantes (normalement 2)
          const finalPages = pdf.internal.getNumberOfPages();
          const pageWidth = pdf.internal.pageSize.getWidth();   
          const pageHeight = pdf.internal.pageSize.getHeight(); 

          for (let i = 1; i <= finalPages; i++) {
              pdf.setPage(i);
              if (brandingBase64.length > 100) {
                 pdf.addImage(brandingBase64, 'PNG', 0, 0, pageWidth, pageHeight); 
              }
          }
      }).save().then(function() {
          // Succès : Nettoyage
          element.classList.remove('pdf-mode');
          if (btn) {
              btn.textContent = '📄 Télécharger mon rapport PDF';
              btn.disabled = false;
              btn.style.opacity = '1';
          }
          if (typeof window._hsq !== 'undefined') {
             window._hsq.push(['trackCustomBehavioralEvent', { name: 'telechargement_pdf_roi', properties: {} }]);
          }
      }).catch(function(err) {
          console.error('Erreur PDF:', err);
          element.classList.remove('pdf-mode');
          if (btn) {
              btn.textContent = 'Réessayer le téléchargement';
              btn.disabled = false;
              btn.style.opacity = '1';
          }
      });
  }, 200);
}

// Helpers
function formatEuro(value) {
  return new Intl.NumberFormat('fr-FR', { style: 'currency', currency: 'EUR', minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(value);
}
function formatNumber(value) {
  return new Intl.NumberFormat('fr-FR').format(value);
}


// ==========================================
// 2. INITIALISATION (LISTENERS)
// ==========================================
document.addEventListener('DOMContentLoaded', function() {
  const btnCalculate = document.querySelector('.btn-calculate');
  if (btnCalculate) {
    btnCalculate.addEventListener('click', calculerImpactCA);
  }

  const btnDownload = document.querySelector('.btn-download-pdf');
  if (btnDownload) {
    btnDownload.addEventListener('click', downloadPDF);
  }
});